<script setup lang="ts">import { ref } from 'vue';import { session } from '../api';const columns=['项目编号','项目名称*','客户*','年份*','服务类型*','负责人','状态*','开始日期','计划完成日期','实际完成日期','项目/采购标的金额','服务合同额（汇总，可空）','造价最终成果金额（可空）','备注'];const preview=ref<any>(),error=ref(''),loading=ref(false);function download(){const csv='\ufeff'+columns.join(',')+'\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='历史项目导入模板.csv';a.click();URL.revokeObjectURL(a.href)}async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';loading.value=true;try{const fd=new FormData();fd.append('file',file);const r=await fetch('/api/v1/imports/history/preview',{method:'POST',headers:{Authorization:`Bearer ${session.token}`},body:fd});const v=await r.json();if(!r.ok)throw new Error(v.message||'预检失败');preview.value=v}catch(e){error.value=(e as Error).message}finally{loading.value=false}}async function confirm(){loading.value=true;try{const r=await fetch(`/api/v1/imports/history/${preview.value.id}/confirm`,{method:'POST',headers:{Authorization:`Bearer ${session.token}`}});const v=await r.json();if(!r.ok)throw new Error(v.message||'导入失败');preview.value={...preview.value,imported:v.created,done:true}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script><template><div style="max-width:850px"><h1 class="title">导入历史项目</h1><p class="subtitle">把过去项目放进同一个长期项目库。导入会保存原始文件与批次预检结果。</p><div class="tabs"><button class="tab" :class="{active:!preview}">01 下载模板</button><button class="tab" :class="{active:preview&&!preview.done}">02 上传并检查</button><button class="tab" :class="{active:preview?.done}">03 确认导入</button></div><section v-if="!preview" class="empty" style="margin-top:38px"><i>↓</i><h3>下载模板并上传 Excel</h3><p>仅支持固定的 .xlsx/.xls 模板；导入前会检查必填字段和可能的项目重复。</p><button class="button secondary" @click="download">下载历史项目模板</button><label class="button primary" style="margin-left:10px">{{loading?'检查中…':'选择 Excel 文件'}}<input type="file" accept=".xlsx,.xls" hidden @change="upload"/></label><p v-if="error" class="error">{{error}}</p></section><section v-else class="form-section"><div class="kpis" style="margin-top:0"><div class="kpi"><div class="kpi-num">{{preview.total}}</div><div class="kpi-label">读取行数</div></div><div class="kpi"><div class="kpi-num">{{preview.validCount}}</div><div class="kpi-label">准备新增</div></div><div class="kpi"><div class="kpi-num">{{preview.duplicateCount}}</div><div class="kpi-label">可能重复（忽略）</div></div><div class="kpi"><div class="kpi-num">{{preview.errors.length}}</div><div class="kpi-label">需要修改</div></div></div><div v-if="preview.errors.length" class="list" style="margin-top:24px"><div v-for="e in preview.errors" class="list-row"><b>第 {{e.row}} 行</b><span class="error">{{e.message}}</span></div></div><p v-if="preview.done" class="success">已成功导入 {{preview.imported}} 个项目。</p><div class="actions"><button class="button secondary" @click="preview=undefined">重新上传</button><button class="button primary" :disabled="loading||preview.errors.length||preview.done" @click="confirm">{{preview.done?'导入已完成':`确认导入 ${preview.validCount} 个项目 →`}}</button></div></section></div></template>
